def esc(v): return str(v).replace('|','\\|').replace('\n','<br>')
for role in roles:
    lines.extend([f"### {role['title']}",'', '| ID / экран | Цель | Вход и главное действие | Следующие экраны | Доступ | Основа / приоритет | Состояния |',
                  '| --- | --- | --- | --- | --- | --- | --- |'])
    for v in screens:
        if v['role'] != role['id']: continue
        values = [f"{v['id']} — {v['title']}",v['goal'],f"{v['entry']} → {v['action']}",', '.join(v['next']),v['access'],f"{v['source']} / {v['priority']}",v['states']]
